std::priority_queue<std::pair<double, int>, std::vector<std::pair<double, int>>, std::greater<std::pair<double, int>>> open_set;
std::unordered_map<int, double> g_score;
std::unordered_map<int, int> parent;
std::unordered_set<int> closed_set;

auto heuristic = [&](int node_idx) -> double {
    const Node& node = graph.getNode(node_idx);
    const Node& end_node = graph.getNode(end_idx);
    double dx = node.x - end_node.x;
    double dy = node.y - end_node.y;
    return std::sqrt(dx * dx + dy * dy);
};

open_set.push({0.0, start_idx});
g_score[start_idx] = 0.0;

while (!open_set.empty()) {
    int current = open_set.top().second;
    open_set.pop();

    if (current == end_idx) {
        std::vector<Node> path;
        int node = end_idx;
        while (node != start_idx) {
            path.push_back(graph.getNode(node));
            node = parent[node];
        }
        path.push_back(graph.getNode(start_idx));
        std::reverse(path.begin(), path.end());
        return path;
    }

    if (closed_set.count(current)) {
        continue;
    }
    closed_set.insert(current);

    for (const auto& neighbor : graph.getNeighbors(current)) {
        int neighbor_idx = neighbor.first;
        double edge_cost = neighbor.second;

        if (closed_set.count(neighbor_idx)) {
            continue;
        }

        double tentative_g = g_score[current] + edge_cost;

        if (!g_score.count(neighbor_idx) || tentative_g < g_score[neighbor_idx]) {
            parent[neighbor_idx] = current;
            g_score[neighbor_idx] = tentative_g;
            double f_score = tentative_g + heuristic(neighbor_idx);
            open_set.push({f_score, neighbor_idx});
        }
    }
}

return std::vector<Node>();
// END_CODE

